-- Migration 0212 — localized help content (es / fr-CA) with EN fallback.
--
-- The base article (mig 0210/0211) holds canonical EN copy. This table
-- holds per-locale overrides of title/summary/body so es + fr-CA visitors
-- read help in their language; a missing row (or null column) falls back
-- to the base article. Mirrors the legal_documents per-locale pattern.
--
-- Idempotent per drizzle/TEMPLATE.md.

CREATE TABLE IF NOT EXISTS help_content_translations (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id  UUID NOT NULL REFERENCES articles(id) ON DELETE CASCADE,
  locale      VARCHAR(10) NOT NULL,
  title       VARCHAR(255),
  summary     TEXT,
  body_md     TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_help_content_translations_article_locale
  ON help_content_translations (article_id, locale);

-- Seed es + fr-CA for the consolidated FAQ + guide articles. VALUES
-- (slug, locale, title, summary, body) joined to the base articles by the
-- editorial author + slug. ON CONFLICT keeps re-runs a no-op.
INSERT INTO help_content_translations (article_id, locale, title, summary, body_md)
SELECT a.id, m.locale, m.title, m.summary, m.body
FROM (VALUES
  -- ── FAQs (es) ──────────────────────────────────────────────────────
  ('faq-create-first-video-resume','es','¿Cómo creo mi primer currículum en video?','Crea un currículum en video desde la sección Currículums: sube el tuyo o genéralo con IA.',E'Para crear tu currículum en video, ve a la sección Currículums y haz clic en «Crear currículum en video». Puedes subir tu propio video o usar nuestra herramienta de IA para generarlo a partir de tu currículum existente.'),
  ('faq-supported-file-formats','es','¿Qué formatos de archivo se admiten?','Video MP4/MOV/AVI (máx. 100 MB); documentos PDF/DOC/DOCX (máx. 10 MB).',E'Admitimos formatos de video comunes (MP4, MOV, AVI) y PDF, DOC, DOCX para currículums de texto. El tamaño máximo es de 100 MB para videos y 10 MB para documentos.'),
  ('faq-set-up-profile','es','¿Cómo configuro mi perfil?','La incorporación te guía: datos, experiencia, habilidades y un currículum.',E'Después de registrarte, te guiaremos por el proceso de incorporación. Completa tu perfil añadiendo tu información personal, experiencia laboral, habilidades y sube tu currículum o crea uno en video.'),
  ('faq-change-password','es','¿Cómo cambio mi contraseña?','Ajustes > Cuenta > Cambiar contraseña.',E'Ve a Ajustes > Cuenta y haz clic en «Cambiar contraseña». Deberás introducir tu contraseña actual y elegir una nueva.'),
  ('faq-change-persona-type','es','¿Puedo cambiar mi rol después de registrarme?','Sí: cambia tu rol en los ajustes de perfil; modifica tu panel y funciones.',E'Sí, puedes actualizar tu rol (Candidato, Reclutador, Empleador) en los ajustes de tu perfil. Ten en cuenta que esto cambiará tu panel y las funciones disponibles.'),
  ('faq-delete-account','es','¿Cómo elimino mi cuenta?','Ajustes > Cuenta > Eliminar cuenta — permanente e irreversible.',E'La eliminación de la cuenta se realiza desde Ajustes > Cuenta > Eliminar cuenta. Esta acción es permanente y no se puede deshacer.'),
  ('faq-good-video-resume','es','¿Qué hace bueno a un currículum en video?','Que dure 1-3 min, buena luz, audio claro, habilidades clave y una llamada a la acción.',E'Un buen currículum en video debe durar de 1 a 3 minutos, presentarse profesionalmente, destacar tus habilidades y experiencia clave e incluir una llamada a la acción clara. Usa buena iluminación y calidad de audio.'),
  ('faq-edit-video-resume','es','¿Puedo editar mi currículum en video después de subirlo?','Edita título/descripción/etiquetas; sube una nueva versión para cambiar el video.',E'Sí, puedes editar el título, la descripción y las etiquetas. Para cambiar el contenido del video, deberás subir una versión nueva.'),
  ('faq-private-video-resume','es','¿Cómo hago privado mi currículum en video?','Cambia la visibilidad a Privado/No listado/Público en los ajustes del video.',E'En los ajustes de tu currículum en video puedes cambiar la visibilidad a «Privado», «No listado» o «Público». Los videos privados solo los ves tú.'),
  ('faq-job-matching','es','¿Cómo funciona la coincidencia de empleos?','La IA te empareja según perfil, habilidades y preferencias; ajústalas en Ajustes.',E'Nuestra IA analiza tu perfil, habilidades y preferencias para emparejarte con oportunidades relevantes. Puedes refinar las coincidencias actualizando tus preferencias en Ajustes.'),
  ('faq-track-applications','es','¿Puedo hacer seguimiento de mis postulaciones?','Sí: la sección Empleos tiene un rastreador con recordatorios de seguimiento.',E'Sí, la sección Empleos incluye un rastreador de postulaciones donde puedes ver el estado de todas tus solicitudes y programar recordatorios de seguimiento.'),
  ('faq-job-match-notifications','es','¿Cómo recibo avisos de nuevas coincidencias de empleo?','Activa las notificaciones de empleo en Ajustes > Notificaciones (correo o push).',E'Activa las notificaciones de empleo en Ajustes > Notificaciones. Puedes elegir recibir avisos por correo electrónico o notificaciones push.'),
  ('faq-post-a-job','es','¿Cómo publico una oferta de empleo?','Empleos > Publicar empleo — añade detalles, requisitos e info de la empresa.',E'Ve a la sección Empleos y haz clic en «Publicar nuevo empleo». Completa los detalles, los requisitos y la información de la empresa. Tu oferta será visible para los candidatos que coincidan.'),
  ('faq-search-candidates','es','¿Puedo buscar candidatos por criterios específicos?','Sí: filtra candidatos en Personas por habilidades, experiencia y ubicación; guarda búsquedas.',E'Sí, usa la sección Personas para buscar y filtrar candidatos por habilidades, nivel de experiencia, ubicación y otros criterios. Puedes guardar búsquedas para usarlas más tarde.'),
  ('faq-candidate-pipeline','es','¿Cómo gestiono mi cartera de candidatos?','Sigue a los candidatos por las etapas de contratación en la vista de cartera del panel.',E'El panel ofrece una vista de cartera donde puedes seguir a los candidatos por las distintas etapas de tu proceso de contratación, desde el primer contacto hasta la contratación.'),

  -- ── FAQs (fr-CA) ───────────────────────────────────────────────────
  ('faq-create-first-video-resume','fr-CA','Comment créer mon premier CV vidéo?','Créez un CV vidéo depuis la section CV : téléversez le vôtre ou générez-le avec l''IA.',E'Pour créer votre CV vidéo, allez à la section CV et cliquez sur « Créer un CV vidéo ». Vous pouvez téléverser votre propre vidéo ou utiliser notre outil d''IA pour en générer un à partir de votre CV existant.'),
  ('faq-supported-file-formats','fr-CA','Quels formats de fichiers sont pris en charge?','Vidéo MP4/MOV/AVI (max 100 Mo); documents PDF/DOC/DOCX (max 10 Mo).',E'Nous prenons en charge les formats vidéo courants (MP4, MOV, AVI) ainsi que PDF, DOC et DOCX pour les CV texte. La taille maximale est de 100 Mo pour les vidéos et de 10 Mo pour les documents.'),
  ('faq-set-up-profile','fr-CA','Comment configurer mon profil?','L''intégration vous guide : coordonnées, expérience, compétences et un CV.',E'Après votre inscription, nous vous guiderons à travers le processus d''intégration. Complétez votre profil en ajoutant vos renseignements personnels, votre expérience, vos compétences et en téléversant votre CV ou en créant un CV vidéo.'),
  ('faq-change-password','fr-CA','Comment changer mon mot de passe?','Paramètres > Compte > Changer le mot de passe.',E'Allez dans Paramètres > Compte et cliquez sur « Changer le mot de passe ». Vous devrez saisir votre mot de passe actuel et en choisir un nouveau.'),
  ('faq-change-persona-type','fr-CA','Puis-je changer mon rôle après mon inscription?','Oui : changez votre rôle dans les paramètres du profil; cela modifie votre tableau de bord.',E'Oui, vous pouvez mettre à jour votre rôle (Chercheur d''emploi, Recruteur, Employeur) dans les paramètres de votre profil. Notez que cela changera votre tableau de bord et les fonctions disponibles.'),
  ('faq-delete-account','fr-CA','Comment supprimer mon compte?','Paramètres > Compte > Supprimer le compte — permanent et irréversible.',E'La suppression du compte se fait depuis Paramètres > Compte > Supprimer le compte. Cette action est permanente et irréversible.'),
  ('faq-good-video-resume','fr-CA','Qu''est-ce qu''un bon CV vidéo?','1 à 3 min, bon éclairage, son clair, compétences clés et un appel à l''action.',E'Un bon CV vidéo devrait durer de 1 à 3 minutes, être présenté de façon professionnelle, mettre en valeur vos compétences et votre expérience clés, et inclure un appel à l''action clair. Utilisez un bon éclairage et un son de qualité.'),
  ('faq-edit-video-resume','fr-CA','Puis-je modifier mon CV vidéo après le téléversement?','Modifiez le titre, la description et les étiquettes; téléversez une nouvelle version pour changer la vidéo.',E'Oui, vous pouvez modifier le titre, la description et les étiquettes. Pour changer le contenu vidéo, vous devrez téléverser une nouvelle version.'),
  ('faq-private-video-resume','fr-CA','Comment rendre mon CV vidéo privé?','Réglez la visibilité à Privé/Non répertorié/Public dans les paramètres de la vidéo.',E'Dans les paramètres de votre CV vidéo, vous pouvez régler la visibilité à « Privé », « Non répertorié » ou « Public ». Les vidéos privées ne sont visibles que par vous.'),
  ('faq-job-matching','fr-CA','Comment fonctionne le jumelage d''emplois?','L''IA vous jumelle selon votre profil, vos compétences et vos préférences; ajustez-les dans les Paramètres.',E'Notre IA analyse votre profil, vos compétences et vos préférences pour vous jumeler à des occasions pertinentes. Vous pouvez affiner les jumelages en mettant à jour vos préférences dans les Paramètres.'),
  ('faq-track-applications','fr-CA','Puis-je suivre mes candidatures?','Oui : la section Emplois comporte un suivi avec des rappels de relance.',E'Oui, la section Emplois comprend un outil de suivi des candidatures où vous pouvez surveiller l''état de toutes vos demandes et programmer des rappels de relance.'),
  ('faq-job-match-notifications','fr-CA','Comment être avisé des nouveaux jumelages d''emplois?','Activez les notifications d''emploi dans Paramètres > Notifications (courriel ou push).',E'Activez les notifications d''emploi dans Paramètres > Notifications. Vous pouvez choisir de recevoir des alertes par courriel ou par notification push.'),
  ('faq-post-a-job','fr-CA','Comment publier une offre d''emploi?','Emplois > Publier une offre — ajoutez les détails, les exigences et l''info de l''entreprise.',E'Allez à la section Emplois et cliquez sur « Publier une nouvelle offre ». Remplissez les détails, les exigences et les renseignements sur l''entreprise. Votre offre sera visible par les candidats correspondants.'),
  ('faq-search-candidates','fr-CA','Puis-je chercher des candidats selon des critères précis?','Oui : filtrez les candidats dans Personnes par compétences, expérience et lieu; enregistrez vos recherches.',E'Oui, utilisez la section Personnes pour rechercher et filtrer les candidats par compétences, niveau d''expérience, lieu et autres critères. Vous pouvez enregistrer vos recherches pour plus tard.'),
  ('faq-candidate-pipeline','fr-CA','Comment gérer mon bassin de candidats?','Suivez les candidats à travers les étapes d''embauche dans la vue bassin du tableau de bord.',E'Le tableau de bord offre une vue « bassin » où vous pouvez suivre les candidats à travers les différentes étapes de votre processus d''embauche, du premier contact à l''embauche.'),

  -- ── Guides (es) ────────────────────────────────────────────────────
  ('guide-getting-started','es','Primeros pasos con hired.video','Configura tu perfil, crea tu primer currículum en video y activa la coincidencia de empleos en menos de 15 minutos.',E'Configura tu cuenta y publica tu primer currículum en video en menos de 15 minutos.\n\n1. **Completa tu perfil** — añade tu experiencia, habilidades y una foto.\n2. **Crea un currículum en video** — sube un clip o genéralo con el Studio de IA.\n3. **Define tu visibilidad** — elige Público, No listado o Privado por elemento.\n4. **Activa la coincidencia de empleos** — configura tus preferencias en Ajustes.\n\n👉 Abre el tutorial interactivo completo en [/guides/getting-started](/guides/getting-started).'),
  ('guide-video-best-practices','es','Buenas prácticas para currículums en video','Que dure 1-3 min, buena luz, audio claro, una sola historia y una llamada a la acción clara.',E'Un buen currículum en video es corto, bien iluminado y termina con una petición clara.\n\n- **Que dure 1-3 minutos.** Empieza con tu mejor gancho en los primeros 5 segundos.\n- **Ilumina tu cara** de frente y encuadra a la altura de los ojos.\n- **El buen audio supera al buen video** — usa una sala silenciosa o un micrófono sencillo.\n- **Cuenta una sola historia**, resalta 2-3 habilidades clave y cierra con una llamada a la acción.\n\n👉 Consulta la guía completa con ejemplos en [/guides/video-best-practices](/guides/video-best-practices).'),
  ('guide-networking','es','Consejos de networking','Construye conexiones que se multiplican: aporta valor, da seguimiento rápido y lleva tu cartera.',E'Tu red es tu canal de búsqueda de empleo de mayor impacto. Constrúyela con intención.\n\n- **Aporta valor primero**, no pidas — comparte trabajo, comenta y presenta personas.\n- **Da seguimiento en 24 horas** tras cualquier conversación relevante.\n- **Lleva una cartera sencilla** — registra a quién contactaste y cuándo retomar.\n- **Usa tu currículum en video** como una presentación cálida y memorable.\n\n👉 Lee el manual completo de networking en [/guides/networking](/guides/networking).'),
  ('guide-job-search','es','Estrategias de búsqueda de empleo','Apunta con precisión, adapta cada postulación, da seguimiento y prepárate para las entrevistas.',E'Gestiona tu búsqueda como un embudo: enfoca, postula, da seguimiento, convierte.\n\n- **Enfoca bien** — una lista de roles concreta supera a postular sin rumbo.\n- **Adapta cada postulación** con las herramientas de currículum y un video específico.\n- **Haz seguimiento** en el rastreador de Empleos y programa recordatorios.\n- **Prepárate** con las herramientas de práctica de entrevistas antes de cada ronda.\n\n👉 Obtén la guía completa en [/guides/job-search](/guides/job-search).'),
  ('guide-tutorials','es','Tutoriales','Tutoriales paso a paso de cada función: currículums, el Studio de video, búsqueda de empleo y reclutamiento.',E'Tutoriales paso a paso de cada función de hired.video — currículums, el Studio de video, búsqueda de empleo y herramientas de reclutamiento.\n\nEmpieza por lo básico y avanza hacia flujos avanzados como el video generado por IA, el editor de línea de tiempo y las carteras de candidatos.\n\n👉 Explora todos los tutoriales en [/guides/tutorials](/guides/tutorials).'),
  ('guide-workforce','es','Personal y hojas de tiempo (para agencias)','Back-office de agencia: invita empleados, registra tiempo, aprueba hojas, genera facturas y controla el margen.',E'El back-office de la agencia: invita empleados, registra tiempo, aprueba hojas de tiempo, genera facturas, gestiona documentos de cumplimiento y controla el margen.\n\n- **Invita a tu equipo** y asigna sus roles.\n- **Registra y aprueba el tiempo**, luego genera facturas automáticamente.\n- **Mantén los documentos de cumplimiento** por trabajador.\n- **Vigila el margen** en todas las colocaciones.\n\n👉 Lee la guía completa para agencias en [/guides/workforce](/guides/workforce).'),

  -- ── Guides (fr-CA) ─────────────────────────────────────────────────
  ('guide-getting-started','fr-CA','Premiers pas avec hired.video','Configurez votre profil, créez votre premier CV vidéo et activez le jumelage d''emplois en moins de 15 minutes.',E'Configurez votre compte et publiez votre premier CV vidéo en moins de 15 minutes.\n\n1. **Complétez votre profil** — ajoutez votre expérience, vos compétences et une photo.\n2. **Créez un CV vidéo** — téléversez un clip ou générez-en un avec le Studio d''IA.\n3. **Définissez votre visibilité** — choisissez Public, Non répertorié ou Privé par élément.\n4. **Activez le jumelage d''emplois** — réglez vos préférences dans les Paramètres.\n\n👉 Ouvrez le guide interactif complet à [/guides/getting-started](/guides/getting-started).'),
  ('guide-video-best-practices','fr-CA','Bonnes pratiques pour le CV vidéo','1 à 3 min, bon éclairage, son clair, une seule histoire et un appel à l''action clair.',E'Un bon CV vidéo est court, bien éclairé et se termine par une demande claire.\n\n- **Durée de 1 à 3 minutes.** Commencez par votre meilleure accroche dans les 5 premières secondes.\n- **Éclairez votre visage** de face et cadrez à hauteur des yeux.\n- **Un bon son vaut mieux qu''une bonne image** — utilisez une pièce silencieuse ou un micro simple.\n- **Racontez une seule histoire**, mettez en valeur 2 à 3 compétences clés et terminez par un appel à l''action.\n\n👉 Consultez le guide complet avec des exemples à [/guides/video-best-practices](/guides/video-best-practices).'),
  ('guide-networking','fr-CA','Conseils de réseautage','Bâtissez des relations qui rapportent : apportez de la valeur, relancez vite, suivez votre bassin.',E'Votre réseau est votre canal de recherche d''emploi le plus efficace. Bâtissez-le de façon délibérée.\n\n- **Apportez de la valeur d''abord**, ne demandez pas — partagez du travail, commentez, présentez des gens.\n- **Relancez dans les 24 heures** après toute conversation importante.\n- **Tenez un bassin simple** — notez qui vous avez contacté et quand relancer.\n- **Utilisez votre CV vidéo** comme une présentation chaleureuse et mémorable.\n\n👉 Lisez le guide complet de réseautage à [/guides/networking](/guides/networking).'),
  ('guide-job-search','fr-CA','Stratégies de recherche d''emploi','Ciblez précisément, adaptez chaque candidature, faites un suivi et préparez vos entrevues.',E'Gérez votre recherche comme un entonnoir : ciblez, postulez, relancez, convertissez.\n\n- **Ciblez serré** — une liste de postes précise vaut mieux que postuler à l''aveugle.\n- **Adaptez chaque candidature** avec les outils de CV et une vidéo propre au poste.\n- **Faites le suivi** dans l''outil de suivi des Emplois et programmez des rappels.\n- **Préparez-vous** avec les outils de pratique d''entrevue avant chaque ronde.\n\n👉 Obtenez le guide complet à [/guides/job-search](/guides/job-search).'),
  ('guide-tutorials','fr-CA','Tutoriels','Tutoriels étape par étape pour chaque fonction : CV, Studio vidéo, recherche d''emploi et recrutement.',E'Tutoriels étape par étape pour chaque fonction de hired.video — CV, Studio vidéo, recherche d''emploi et outils de recrutement.\n\nCommencez par les bases et progressez vers des flux avancés comme la vidéo générée par IA, l''éditeur de montage et les bassins de candidats.\n\n👉 Parcourez tous les tutoriels à [/guides/tutorials](/guides/tutorials).'),
  ('guide-workforce','fr-CA','Main-d''œuvre et feuilles de temps (pour agences)','Back-office d''agence : invitez des employés, saisissez le temps, approuvez les feuilles, générez des factures, suivez la marge.',E'Le back-office de l''agence : invitez des employés, saisissez le temps, approuvez les feuilles de temps, générez des factures, gérez les documents de conformité et suivez la marge.\n\n- **Invitez votre équipe** et définissez leurs rôles.\n- **Saisissez et approuvez le temps**, puis générez les factures automatiquement.\n- **Conservez les documents de conformité** par travailleur.\n- **Surveillez la marge** sur tous les placements.\n\n👉 Lisez le guide complet pour agences à [/guides/workforce](/guides/workforce).')
) AS m(slug, locale, title, summary, body)
JOIN articles a
  ON a.user_id = (md5('editorial@hired.video'))::uuid AND a.slug = m.slug
ON CONFLICT (article_id, locale) DO NOTHING;
